package com.smartspend.service;
import com.smartspend.dao.TransactionDAO;import com.smartspend.model.Transaction;import java.time.LocalDate;import java.util.*;
public class TransactionService {private final TransactionDAO dao=new TransactionDAO(); public void create(Transaction t){validate(t);dao.create(t);} public void update(Transaction t){validate(t);dao.update(t);} public void delete(int id,int uid){dao.delete(id,uid);} public List<Transaction> search(int uid,String text,String type,String cat,LocalDate from,LocalDate to,Double min,Double max,String sort){return dao.search(uid,text,type,cat,from,to,min,max,sort);} public Map<String,Double> monthlyTotals(int u,int y,int m){return dao.monthlyTotals(u,y,m);} public Map<String,Double> categoryTotals(int u,int y,int m){return dao.categoryTotals(u,y,m);} private void validate(Transaction t){if(t.getAmount()<=0||!Double.isFinite(t.getAmount()))throw new IllegalArgumentException("Amount must be greater than zero.");if(t.getDescription()==null||t.getDescription().isBlank())throw new IllegalArgumentException("Description is required.");if(t.getTransactionDate()==null)throw new IllegalArgumentException("Date is required.");if(t.getCategoryId()<=0)throw new IllegalArgumentException("Choose a category.");}}
